  ON clients FOR INSERT
  WITH CHECK (is_admin());

CREATE POLICY "Admins can update clients"
  ON clients FOR UPDATE
  USING (is_admin());

-- Technicians can view clients for their tickets
CREATE POLICY "Technicians can view clients for their tickets"
  ON clients FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM tickets
      WHERE tickets.client_id = clients.id
        AND tickets.technician_id = current_technician_id()
    )
  );

